import * as readline from 'node:readline';
import { PassThrough } from 'node:stream';
function main(): void {
  const input: any = new PassThrough();
  const rl: any = readline.createInterface({ input, terminal: false });
  const seen: string[] = [];
  const first = () => { seen.push('first'); };
  rl.on('line', (l: string) => { seen.push('line:' + l); });
  console.log(typeof rl._events.line, rl.listenerCount('line'));
  rl.on('line', first);
  console.log(Array.isArray(rl._events.line), rl.listenerCount('line'), rl.eventNames().indexOf('line') >= 0);
  rl.once('close', () => { seen.push('close'); });
  rl.off('line', first);
  console.log(typeof rl._events.line, rl.listenerCount('line'));
  input.write('a\nb\n');
  input.end();
  rl.on('close', () => { console.log(seen.join(',')); });
}
